글 = input("글: ")
개수 = {}
for 글자 in 글:
    if 글자 in 개수:
        개수[글자] += 1
    else:
        개수[글자] = 1
for 글자 in 개수:
    print(글자, 개수[글자])

한영 = {"사과": "apple", "개": "dog", "책": "book"}
영한 = {}
for 한글 in 한영:
    영한[한영[한글]] = 한글
낱말 = input("영어 낱말: ")
if 낱말 in 영한:
    print(영한[낱말])
else:
    print("몰라요")

낱말 = input("낱말: ")
개수 = {}
for 글자 in 낱말:
    if 글자 in 개수:
        개수[글자] += 1
    else:
        개수[글자] = 1
찾은 = 0
for 글자 in 개수:
    if 개수[글자] >= 2:
        print(글자, 개수[글자])
        찾은 += 1
if 찾은 == 0:
    print("없어요")

가격 = {"사과": 1000, "귤": 500, "우유": 2500}
개수 = {}
while True:
    물건 = input("물건: ")
    if 물건 == "끝":
        break
    if 물건 in 개수:
        개수[물건] += 1
    else:
        개수[물건] = 1
합 = 0
for 물건 in 개수:
    값 = 가격[물건] * 개수[물건]
    print(물건, 개수[물건], "개", 값, "원")
    합 += 값
print("합", 합, "원")
